package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.lang.reflect.Modifier;
import java.util.concurrent.atomic.AtomicInteger;
public class RootImageSeriesIntentTest {
 private static final long NOW=1000,UTC=RootImageSeriesScope.STARTS_UTC+1000;
 private RootImageSeriesIntent series(RealCaptureClaim.ProcessEpoch e){return VisibleCaptureAuthority.fixtureSeriesIntent(new Object(),new Object(),e,new Object(),NOW,()->UTC);}
 @Test public void originalParentHasNoPublicConstructorOrBusinessAuthority(){for(var c:RootImageSeriesIntent.class.getDeclaredConstructors())assertTrue(Modifier.isPrivate(c.getModifiers()));for(var c:CaptureSessionRuntime.SeriesCompletion.class.getDeclaredConstructors())assertTrue(Modifier.isPrivate(c.getModifiers()));var s=series(new RealCaptureClaim.ProcessEpoch());assertFalse(s.live());assertEquals(51000,s.sessionEnd());}
 @Test public void firstGrantHasOneBurnAndCannotBeReissued(){var e=new RealCaptureClaim.ProcessEpoch();var s=series(e);Object o=new Object();var g=VisibleCaptureAuthority.fixtureSeriesGrant(s,1,e,o,NOW,11000,null);AtomicInteger burns=new AtomicInteger();assertEquals(RealCaptureClaim.Outcome.CONSUMED,RealCaptureClaim.consume(g,e,o,NOW,(id,meta)->{assertTrue(meta.contains("FIXTURE_ONLY"));burns.incrementAndGet();}));assertEquals(RealCaptureClaim.Outcome.REJECTED,RealCaptureClaim.consume(g,e,o,NOW,(id,meta)->burns.incrementAndGet()));assertEquals(1,burns.get());assertThrows(SecurityException.class,()->VisibleCaptureAuthority.fixtureSeriesGrant(s,1,e,new Object(),NOW,11000,null));}
 @Test public void laterFrameRequiresActualOpaqueCompletion(){var e=new RealCaptureClaim.ProcessEpoch();var s=series(e);VisibleCaptureAuthority.fixtureSeriesGrant(s,1,e,new Object(),NOW,11000,null);assertThrows(SecurityException.class,()->VisibleCaptureAuthority.fixtureSeriesGrant(s,2,e,new Object(),NOW,11000,null));assertThrows(SecurityException.class,()->VisibleCaptureAuthority.fixtureSeriesGrant(s,3,e,new Object(),NOW,11000,null));}
 @Test public void wrongEpochExpiredCancelledAndInvalidIndexReject(){var e=new RealCaptureClaim.ProcessEpoch();var s=series(e);assertThrows(SecurityException.class,()->VisibleCaptureAuthority.fixtureSeriesGrant(s,1,new RealCaptureClaim.ProcessEpoch(),new Object(),NOW,11000,null));assertThrows(SecurityException.class,()->VisibleCaptureAuthority.fixtureSeriesGrant(s,0,e,new Object(),NOW,11000,null));assertThrows(SecurityException.class,()->VisibleCaptureAuthority.fixtureSeriesGrant(s,4,e,new Object(),NOW,11000,null));assertThrows(SecurityException.class,()->VisibleCaptureAuthority.fixtureSeriesGrant(s,1,e,new Object(),51000,52000,null));s.cancel();assertFalse(s.current(NOW));assertThrows(SecurityException.class,()->VisibleCaptureAuthority.fixtureSeriesGrant(s,1,e,new Object(),NOW,11000,null));}
 @Test public void deadlineCannotExtendOriginalParent(){var e=new RealCaptureClaim.ProcessEpoch();var s=series(e);assertThrows(SecurityException.class,()->VisibleCaptureAuthority.fixtureSeriesGrant(s,1,e,new Object(),NOW,s.sessionEnd()+1,null));assertThrows(SecurityException.class,()->VisibleCaptureAuthority.fixtureSeriesGrant(s,1,e,new Object(),NOW,NOW,null));}
 @Test public void sourceBindingIsExactWindowActivityTaskAndShape(){var s=series(new RealCaptureClaim.ProcessEpoch());var a=BingNavigationFixture.result(BingNavigationSnapshot.Kind.TEMPLATE,NOW).ready();assertNotNull(a);assertFalse(s.sourceMatches(2,a));assertTrue(s.sourceMatches(1,a));assertTrue(s.sourceMatches(2,BingNavigationFixture.result(BingNavigationSnapshot.Kind.TEMPLATE,NOW+1).ready()));assertFalse(s.sourceMatches(2,BingNavigationFixture.result(BingNavigationSnapshot.Kind.TEMPLATE,NOW,"aab","ddd","15").ready()));assertFalse(s.sourceMatches(2,BingNavigationFixture.result(BingNavigationSnapshot.Kind.TEMPLATE,NOW,"aaa","dde","15").ready()));assertFalse(s.sourceMatches(2,BingNavigationFixture.result(BingNavigationSnapshot.Kind.TEMPLATE,NOW,"aaa","ddd","16").ready()));assertFalse(s.sourceMatches(2,BingNavigationFixture.result(BingNavigationSnapshot.Kind.BROWSER,NOW).ready()));}
 @Test public void handoffHasOneActualRequestAndHiddenEvent(){var s=series(new RealCaptureClaim.ProcessEpoch());assertThrows(SecurityException.class,()->s.hiddenHandoff(1));s.requestHandoff(100);assertThrows(SecurityException.class,()->s.requestHandoff(101));assertThrows(SecurityException.class,()->s.hiddenHandoff(99));s.hiddenHandoff(110);assertThrows(SecurityException.class,()->s.hiddenHandoff(111));assertTrue(s.handoffSummary().contains("requestNs=100 hiddenNs=110"));}
 @Test public void metadataBindingDoesNotExportIdentity(){var a=BingNavigationFixture.result(BingNavigationSnapshot.Kind.TEMPLATE,NOW).ready();assertTrue(a.diagnosticActivityMatches("ddd",BingNavigationSnapshot.TEMPLATE,"15"));assertFalse(a.diagnosticActivityMatches("dde",BingNavigationSnapshot.TEMPLATE,"15"));assertTrue(a.diagnosticWindowMatches("aaa"));assertFalse(a.diagnosticWindowMatches("aab"));}
 private String source(String n)throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",n)).replace("\r\n","\n");}
 @Test public void seriesLiveEntryNeverConstructsActorsOrOldContinuations()throws Exception{String r=source("CaptureSessionRuntime.java");String b=r.substring(r.indexOf("static CaptureSessionRuntime startSeries("),r.indexOf("static RootBoundedBusinessIntent approveBounded("));assertFalse(b.contains("NativeAutonomousCardRun"));assertFalse(b.contains("Continuation"));assertFalse(b.contains("new LiveClick"));assertEquals(1,b.split("activity\\.requestHandoff\\(",-1).length-1);assertTrue(b.contains("if(index==1)"));assertTrue(b.contains("EPOCH.retain(run)"));assertTrue(b.contains("ROOT.retain(run,EPOCH,deadline"));assertTrue(r.contains("RootImageSeriesScope.store(activity.getNoBackupFilesDir().toPath(),seriesIndex)"));}
 @Test public void seriesCompletionRequiresActualAuditsAndCandidateRemainsOff()throws Exception{String r=source("CaptureSessionRuntime.java");assertTrue(r.contains("rootCandidate=seriesIntent==null&&"));assertTrue(r.contains("rootPreflightValid=seriesIntent==null&&"));assertTrue(r.contains("if(returnReadIntent!=null||boundedIntent!=null||seriesIntent!=null||RootFamilyDiagnosticProfile.ACTIVE)return null"));assertTrue(r.contains("png.status()==PngImageAudit.Status.MATCH"));assertTrue(r.contains("maa.status()==MaaImageBufferAudit.Status.VERIFIED_EQUAL"));assertTrue(r.contains("readOnlyObservation.capture==readOnlyCapture"));assertTrue(r.contains("maa.allOcrGeometry().nativeRows()>0"));assertTrue(r.contains("if((returnReadIntent!=null||seriesIntent!=null||boundedIntent!=null)&&reportFinal&&released)return;"));}
 @Test public void sharedVisibilityRevokesCurrentSeriesButOldTimerDoesNot()throws Exception{String a=source("DormantCaptureConfirmationActivity.java"),r=source("CaptureSessionRuntime.java");assertTrue(a.contains("seriesIntent==exact&&!seriesFinished"));assertTrue(a.contains("active.seriesIntent()==exact"));assertTrue(r.contains("()->activity.seriesVisibilityRevoked(intent)"));assertTrue(r.contains("private void latchCancel() {\n        if((returnReadIntent!=null||seriesIntent!=null||boundedIntent!=null)&&reportFinal&&released)return;"));String local=r.substring(r.indexOf("private void latchCancel()"),r.indexOf("void onActivityResult("));assertFalse(local.contains("seriesIntent.cancel()"));}
 @Test public void seriesNoIntermediateOrFinalFocusAndBoundedPerFrameViews()throws Exception{String a=source("DormantCaptureConfirmationActivity.java"),u=source("RootCaptureUi.java");String b=a.substring(a.indexOf("void seriesFrameFinished("),a.indexOf("private volatile RootCaptureIntent"));assertFalse(b.contains("moveToFront"));assertFalse(b.contains("restoreOwnTask"));assertFalse(b.contains("new LiveClick"));assertTrue(b.contains("new TerminalSnapshot(true,false,\"BEFORE\",false)"));assertTrue(b.contains("report.length()<=7000"));assertTrue(u.contains("(total+=report.length())>22000"));assertTrue(u.contains("flatCount"));assertTrue(u.contains("floor(H/4)"));}
 @Test public void seriesPngSummaryNeverDisplaysDigests()throws Exception{String r=source("CaptureSessionRuntime.java");String b=r.substring(r.indexOf("static String seriesPngSummary"),r.indexOf("static final class SeriesCompletion"));assertFalse(b.contains("Sha256"));assertFalse(b.contains("safeSummary()"));assertTrue(b.contains("standardEqual="));assertTrue(r.contains("seriesIntent!=null?seriesPngSummary(audit):audit.safeSummary()"));}
 @Test public void extraDiagnosticCommandsAreFixedAndOneShotWithExistingQuarantine()throws Exception{String r=source("ReviewBingNavigation.java");assertTrue(r.contains("if(seriesDiagnosticsSpent)throw"));assertTrue(r.contains("seriesDiagnosticsSpent=true"));assertTrue(r.contains("rootSourcePermit.seriesDiagnosticAllowed()"));assertTrue(r.contains("new String[]{\"/system/bin/dumpsys\",\"activity\",BingNavigationSnapshot.TEMPLATE}"));assertTrue(r.contains("new String[]{\"/system/bin/dumpsys\",\"SurfaceFlinger\"}"));assertTrue(r.contains("quarantine=new Object[]{process,input,stdout,stdin,stderr}"));assertFalse(r.contains("uiautomator"));assertFalse(r.contains("--latency-clear"));}
}
